mapper.select:
SELECT team_code, team_name, sort_order, use_yn, created_at, updated_at
  FROM team
 WHERE team_code = #{teamCode}

mapper.update:
UPDATE team
   SET team_name = #{teamName},
       sort_order = #{sortOrder},
       use_yn = #{useYn},
       updated_at = #{updatedAt}
 WHERE team_code = #{teamCode}
